/** What a personal API token may do: `read` acts as a viewer, `write` acts
 *  with the owner's current role. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the app exposes it. The secret is shown once, at
 * creation, and only its hash is stored — neither ever appears on this type.
