/**
 * Personal API tokens: creation, listing, revocation and bearer authentication.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Most tokens a user may hold at once in one organization. */
const MAX_USABLE_TOKENS = 5;

const SECRET_PREFIX = "tfk_";
const DISPLAY_PREFIX_LENGTH = 12;
const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * The secret is returned here and nowhere else; only its hash is stored.
 */
export async function createApiToken(
  actor: Actor,
  rawInput: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const input = createApiTokenSchema.parse(rawInput);
  assertOrgScope(actor, input.orgId);
  if (input.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(input.orgId));
  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const now = new Date();

  const apiToken = await apiTokenRepo.insertTokenWithinLimit(
    {
      orgId: input.orgId,
      userId: actor.userId,
      name: input.name,
      scope: input.scope,
      tokenHash: hashToken(token),
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + input.expiresInDays * DAY_MS)),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS} active API tokens; revoke one first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
    tokenUserId: apiToken.userId,
  });

  return { token, apiToken };
}

/** Another user's tokens are visible to admins and owners only. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  return apiTokenRepo.listTokensForUser(orgId, userId);
}

/** Revoking an already-revoked token is a no-op that returns it unchanged. */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return (await revokeAndAnnounce(existing, actor.userId)) ?? existing;
}

/**
 * Resolves the `Actor` a bearer token stands for, or `null`. A `read` token
 * always acts as a viewer; a `write` token acts with the member's role as it
 * stands right now.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const stored = await apiTokenRepo.findTokenByHash(hashToken(token));
  if (stored === null || stored.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (stored.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(stored.userId, stored.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchTokenLastUsed(stored.orgId, stored.id, now);

  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/** Revokes a still-live token and publishes the fact; `null` if it was already revoked. */
async function revokeAndAnnounce(
  token: ApiToken,
  actorId: UserId | null,
): Promise<ApiToken | null> {
  const revoked = await apiTokenRepo.revokeToken(
    token.orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) return null;

  await emit("api_token.revoked", {
    ...envelope(revoked.orgId, actorId),
    tokenId: revoked.id,
    name: revoked.name,
    tokenUserId: revoked.userId,
  });
  return revoked;
}

/**
 * A removed member's tokens must stop working with them: everything of theirs
 * in that organization that is not yet revoked (expired ones included) is
 * revoked, with the remover as the audited actor.
 */
export function registerApiTokenListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("member.removed", async (payload) => {
      const tokens = await apiTokenRepo.listUnrevokedTokensForUser(
        payload.orgId,
        payload.userId,
      );
      for (const token of tokens) {
        await revokeAndAnnounce(token, payload.actorId);
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
EOF
