import { beforeEach, describe, expect, it } from "vitest";
import { getDb, members } from "@/server/db";
import { resetTestDb, seedTwoTenants, setupTestDb } from "../helpers/db";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as svc from "@/server/services/api-token-service";
import * as memberSvc from "@/server/services/member-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { ALICE, BOB, ORG_A, ORG_B, makeActor } from "../helpers/factories";

describe("api tokens", () => {
  beforeEach(async () => {
    await setupTestDb();
    await resetTestDb();
    await seedTwoTenants();
    registerEventHandlers();
  });
  it("works", async () => {
    const actor = makeActor({ role: "owner" });
    const { token, apiToken } = await svc.createApiToken(actor, { orgId: ORG_A, name: " ci ", scope: "write", expiresInDays: 1 });
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("ci");
    await expect(svc.createApiToken(makeActor({ role: "viewer" }), { orgId: ORG_A, name: "x", scope: "write", expiresInDays: 1 })).rejects.toThrow(/Permission/);
    const a = await svc.authenticateApiToken(token);
    expect(a).toEqual({ userId: ALICE, orgId: ORG_A, role: "owner" });
    expect((await svc.listApiTokens(actor, ORG_A))[0]!.lastUsedAt).not.toBeNull();
    for (let i = 0; i < 4; i++) await svc.createApiToken(actor, { orgId: ORG_A, name: "x", scope: "read", expiresInDays: 1 });
    await expect(svc.createApiToken(actor, { orgId: ORG_A, name: "x", scope: "read", expiresInDays: 1 })).rejects.toThrow();
    const r1 = await svc.revokeApiToken(actor, ORG_A, apiToken.id);
    const r2 = await svc.revokeApiToken(actor, ORG_A, apiToken.id);
    expect(r2.revokedAt).toBe(r1.revokedAt);
    expect(await svc.authenticateApiToken(token)).toBeNull();
    const page = await activityRepo.listActivity({ orgId: ORG_A, limit: 100, cursor: null, subjectKind: "api_token" });
    expect(page.items.filter((e) => e.action === "api_token.revoked")).toHaveLength(1);
    expect(page.items.filter((e) => e.action === "api_token.created")).toHaveLength(6);
    void getDb; void members; void BOB; void ORG_B; void memberSvc;
  });
});
EOF
